import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"From Chat to Action: What Is an AI Agent?","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/what-is-an-agent.md","filePath":"learn/01-agent-basics/what-is-an-agent.md","lastUpdated":1792595354000}'),o={name:"learn/01-agent-basics/what-is-an-agent.md"};function i(r,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="from-chat-to-action-what-is-an-ai-agent" tabindex="-1">From Chat to Action: What Is an AI Agent? <a class="header-anchor" href="#from-chat-to-action-what-is-an-ai-agent" aria-label="Permalink to &quot;From Chat to Action: What Is an AI Agent?&quot;">​</a></h1><h2 id="from-answering-questions-to-completing-tasks" tabindex="-1">From answering questions to completing tasks <a class="header-anchor" href="#from-answering-questions-to-completing-tasks" aria-label="Permalink to &quot;From answering questions to completing tasks&quot;">​</a></h2><p>Most people use AI by asking a question and waiting for an answer. A language model can summarize what it already knows, but without connected tools it cannot search for current information or take actions in other systems.</p><p>Consider a more involved request: search the past week&#39;s AI news, select five important stories, read the original sources, compare their perspectives, and produce a briefing. Completing it may require searching, fetching pages, checking relevance, comparing sources, searching again when evidence is missing, and writing the report. This is a multi-step task, not a single text generation.</p><p><strong>An AI agent works toward a goal by combining model reasoning, tool use, and feedback from actions.</strong></p><h2 id="llm-workflow-and-agent" tabindex="-1">LLM, workflow, and agent <a class="header-anchor" href="#llm-workflow-and-agent" aria-label="Permalink to &quot;LLM, workflow, and agent&quot;">​</a></h2><p>An LLM interprets input and generates text or recommendations. A workflow follows steps defined in advance, which is useful when the control flow is predictable. An agent uses a model to choose or adapt actions based on what it observes, often calling tools and inspecting their results before deciding what to do next. Real systems can combine workflows and agent decisions.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Receive goal → observe context → choose an action → call a tool</span></span>
<span class="line"><span>      ↑                                         ↓</span></span>
<span class="line"><span>      └──────────── inspect result ─────────────┘</span></span></code></pre></div><p>The loop stops when the goal is met, a limit is reached, or human input is needed.</p><h2 id="common-components" tabindex="-1">Common components <a class="header-anchor" href="#common-components" aria-label="Permalink to &quot;Common components&quot;">​</a></h2><ul><li><strong>Model:</strong> interprets the task and proposes decisions.</li><li><strong>Instructions and context:</strong> describe goals, constraints, and relevant information.</li><li><strong>Tools:</strong> expose capabilities such as search, databases, and APIs.</li><li><strong>Orchestrator:</strong> manages the action loop, tool results, and stopping conditions.</li><li><strong>State or memory:</strong> preserves task progress where needed.</li><li><strong>External controls:</strong> enforce permissions, budgets, validation, and approvals.</li></ul><p>The model is only one component. Reliable agents depend on surrounding software to validate inputs, restrict actions, handle errors, and record events.</p><h2 id="why-the-distinction-matters" tabindex="-1">Why the distinction matters <a class="header-anchor" href="#why-the-distinction-matters" aria-label="Permalink to &quot;Why the distinction matters&quot;">​</a></h2><p>An ordinary text response usually has no direct external effect. An agent can send messages, modify records, trigger deployments, or make purchases through tools. The more consequential the tools, the more important it is to use narrow permissions, explicit limits, and recovery paths.</p><p>For payment-capable agents, the model may propose a purchase, but deterministic software should independently decide whether it satisfies the user&#39;s authorization and spending policy.</p>`,15)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
